(7563204, 1212201, 96751, '<td valign="top">Magnificent shot.  You are indeed fortunate to have seen a wolf in the wild.</td>', 'Magnificent shot.  You are indeed fortunate to have seen a wolf in the wild.', '2018-03-19 19:13:07.000000', NULL, 0),
(7563210, 1212201, 50189, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by tanguera:</b></div><hr/><i> Magnificent shot.  You are indeed fortunate to have seen a wolf in the wild. </i></td></tr></table> <br/> <br/>Thank you for the kind words, we were actually able to see this pack of wolves 2 out of the first 3 days we were in the park.  The first day 7 of the 18 were finishing off a bison kill from the day before.  this picture is from the 3rd day where they had killed an elk the day before.  This wolf is the only one that could be seen, but we could here more of the pack in the woods not far away.  We were put into a spot by the park rangers that was my guess way to close.  It didn''t seem to worried about us, only this one time did it look in our direction.</td>', 'Originally posted by tanguera: Magnificent shot.  You are indeed fortunate to have seen a wolf in the wild.   Thank you for the kind words, we were actually able to see this pack of wolves 2 out of the first 3 days we were in the park.  The first day 7 of the 18 were finishing off a bison kill from the day before.  this picture is from the 3rd day where they had killed an elk the day before.  This wolf is the only one that could be seen, but we could here more of the pack in the woods not far away.  We were put into a spot by the park rangers that was my guess way to close.  It didn''t seem to worried about us, only this one time did it look in our direction.', '2018-03-19 20:56:15.000000', NULL, 0),
(7563478, 1212560, 100831, '<td valign="top">Its worth noting the poetic description of your creation here.</td>', 'Its worth noting the poetic description of your creation here.', '2018-03-21 10:45:39.000000', NULL, 0),
